def transition(table, pk):
    """Compare the previous extract with this one by primary key."""
    def load(day):
        f, head, rows = reader(day, table)
        idx = [head.index(k) for k in pk]
        d = {tuple(r[i] for i in idx): r for r in rows}
        f.close()
        return head, d
